const S17_ADMIN_DEV_SHEET_ID = '1z7PNZtDdC4Z5eLbmTuQdqp0QpJSmuEvx3QvN3VyNTsc';

/* --- Utilities --- */

function _s17Copy(x) { return JSON.parse(JSON.stringify(x)); }
